selector_to_html = {"a[href=\"#module-pyskyfire.thermo.nozzle_loss\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.thermo.nozzle_loss<a class=\"headerlink\" href=\"#module-pyskyfire.thermo.nozzle_loss\" title=\"Link to this heading\">\u00b6</a></h1><p>Efficiency corrections from ideal (ODE) to delivered engine performance.</p><p>CEA, and therefore <a class=\"reference internal\" href=\"../aerothermodynamics/Aerothermodynamics.html#pyskyfire.thermo.aerothermodynamics.Aerothermodynamics\" title=\"pyskyfire.thermo.aerothermodynamics.Aerothermodynamics\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Aerothermodynamics</span></code></a>,\nsolves a one-dimensional equilibrium expansion. Real nozzle flow loses\nperformance to two-dimensional divergence, the wall boundary layer and\nfinite-rate chemistry, and real injectors do not release the full ideal\ncombustion energy. The standard engineering treatment is to keep the ideal\nsolution and multiply it by efficiencies obtained from higher-fidelity codes:</p>", "a[href=\"NozzleLoss.html#pyskyfire.thermo.nozzle_loss.NozzleLoss.apply\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.nozzle_loss.NozzleLoss.apply\">\n<span class=\"sig-name descname\"><span class=\"pre\">apply</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aero</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_amb</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"DeliveredPerformance.html#pyskyfire.thermo.nozzle_loss.DeliveredPerformance\" title=\"pyskyfire.thermo.nozzle_loss.DeliveredPerformance\"><span class=\"pre\">DeliveredPerformance</span></a></span></span></dt><dd><p>Degrade an <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Aerothermodynamics</span></code> design point.</p><p class=\"rubric\">Notes</p><p>Mass flow is passed through unchanged \u2013 the engine burns what it\nburns, and these efficiencies say how much impulse that flow delivers.\nUse <a class=\"reference internal\" href=\"#pyskyfire.thermo.nozzle_loss.NozzleLoss.mass_flow\" title=\"pyskyfire.thermo.nozzle_loss.NozzleLoss.mass_flow\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">mass_flow()</span></code></a> if you instead want the flow a throat area\npasses.</p></dd>", "a[href=\"NozzleLoss.html#pyskyfire.thermo.nozzle_loss.NozzleLoss\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.nozzle_loss.NozzleLoss\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.nozzle_loss.</span></span><span class=\"sig-name descname\"><span class=\"pre\">NozzleLoss</span></span></dt><dd><p>Multiplicative efficiency model taking ideal performance to delivered.</p><p class=\"rubric\">Examples</p></dd>", "a[href=\"#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">\u00b6</a></h2><p>The nozzle discharge coefficient is deliberately <em>not</em> part of the specific\nimpulse chain. It rescales the mass flow that a given throat area passes, not\nthe impulse each unit of propellant delivers, and in the reference above it is\napplied separately (sec. 4.2.3.3). <a class=\"reference internal\" href=\"NozzleLoss.html#pyskyfire.thermo.nozzle_loss.NozzleLoss.mass_flow\" title=\"pyskyfire.thermo.nozzle_loss.NozzleLoss.mass_flow\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">NozzleLoss.mass_flow()</span></code></a> is provided for\nthat purpose; <a class=\"reference internal\" href=\"NozzleLoss.html#pyskyfire.thermo.nozzle_loss.NozzleLoss.apply\" title=\"pyskyfire.thermo.nozzle_loss.NozzleLoss.apply\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">NozzleLoss.apply()</span></code></a> leaves mass flow untouched.</p>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.thermo.nozzle_loss.RL10A_3_3A_ETA_CF\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.nozzle_loss.RL10A_3_3A_ETA_CF\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.nozzle_loss.</span></span><span class=\"sig-name descname\"><span class=\"pre\">RL10A_3_3A_ETA_CF</span></span></dt><dd></dd>", "a[href=\"../aerothermodynamics/Aerothermodynamics.html#pyskyfire.thermo.aerothermodynamics.Aerothermodynamics\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.aerothermodynamics.Aerothermodynamics\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.aerothermodynamics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Aerothermodynamics</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">optimum</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transport</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'equilibrium'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cache</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">minimum_cea_temperature</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">MIN_CEA_TEMPERATURE</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"EfficiencyTable.html#pyskyfire.thermo.nozzle_loss.EfficiencyTable\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.nozzle_loss.EfficiencyTable\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.nozzle_loss.</span></span><span class=\"sig-name descname\"><span class=\"pre\">EfficiencyTable</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mixture_ratio</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chamber_pressure</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">values</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">log_pressure</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Efficiency tabulated against mixture ratio and chamber pressure.</p><p class=\"rubric\">Notes</p><p>Queries outside the tabulated ranges are <strong>clamped</strong> to the edge values\nrather than extrapolated. Efficiency tables of this kind are fits over a\nstated envelope and go badly wrong outside it \u2013 the reference report notes\nthat the vendor tables it compared against can return negative specific\nimpulse when pushed past their intended range.</p></dd>", "a[href=\"NozzleLoss.html#pyskyfire.thermo.nozzle_loss.NozzleLoss.mass_flow\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.nozzle_loss.NozzleLoss.mass_flow\">\n<span class=\"sig-name descname\"><span class=\"pre\">mass_flow</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_c</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">A_t</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">c_star_ideal</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">MR</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p>Mass flow [kg s\u207b\u00b9] through a geometric throat area <code class=\"docutils literal notranslate\"><span class=\"pre\">A_t</span></code> [m\u00b2].</p><p>Applies both the discharge coefficient and the characteristic-velocity\nefficiency:</p></dd>", "a[href=\"DeliveredPerformance.html#pyskyfire.thermo.nozzle_loss.DeliveredPerformance\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.nozzle_loss.DeliveredPerformance\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.nozzle_loss.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DeliveredPerformance</span></span></dt><dd><p>Performance after efficiencies, at unchanged propellant flow.</p></dd>", "a[href=\"#pyskyfire.thermo.nozzle_loss.RL10A_3_3A_LOSS\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.nozzle_loss.RL10A_3_3A_LOSS\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.nozzle_loss.</span></span><span class=\"sig-name descname\"><span class=\"pre\">RL10A_3_3A_LOSS</span></span></dt><dd></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
